<?php
namespace App\Http\Controllers;
use App\Models\{Booking,Listing};use Illuminate\Http\Request;
class BookingController extends Controller { public function store(Request $r, Listing $listing){$r->validate(['start_at'=>'nullable|date','end_at'=>'nullable|date|after_or_equal:start_at','notes'=>'nullable|max:1000','address'=>'required|max:500']);$b=Booking::create(['listing_id'=>$listing->id,'customer_id'=>$r->user()->id,'provider_id'=>$listing->provider_id,'start_at'=>$r->start_at,'end_at'=>$r->end_at,'amount'=>$listing->price,'notes'=>$r->notes,'address'=>$r->address]);$listing->provider->notify(new \App\Notifications\BookingCreated($b));return back()->with('success','Booking request sent.');} public function provider(Request $r){$bookings=Booking::with(['listing','customer'])->where('provider_id',$r->user()->id)->latest()->paginate(10);return view('provider.bookings',compact('bookings'));} public function update(Request $r, Booking $booking){abort_unless($booking->provider_id===$r->user()->id,403);$r->validate(['status'=>'required|in:confirmed,rejected,completed,cancelled']);$booking->update(['status'=>$r->status]);return back()->with('success','Booking updated.');}}
